{
  "findings": [
    {
      "ref": "[D503]",
      "area": "age_gating",
      "claim": "A parent reports that children under 13 can create an account only with parental consent and must use a Parent Linked Account for supervision.",
      "stance": "risk",
      "quote": "Users ages 5 and older may create an Account, but certain features for the Services must be enabled by a parent or legal guardian through our Parental Controls."
    },
    {
      "ref": "[D503]",
      "area": "age_gating",
      "claim": "A parent reports that children under 18 must have a parent or legal guardian accept the terms on their behalf.",
      "stance": "risk",
      "quote": "If you are a User under the age of 18 (a “minor”), you must create the Account together with your parent or legal guardian. Your parent or legal guardian must accept these Roblox Terms on your behalf and allow you to use the Services."
    },
    {
      "ref": "[D503]",
      "area": "contact",
      "claim": "A parent reports that voice chat is available but can be turned off via parental controls.",
      "stance": "mitigation",
      "quote": "You can find tools and resources to help you manage your family's experience on Roblox at Parental Controls."
    },
    {
      "ref": "[D503]",
      "area": "money",
      "claim": "A parent reports that the app offers in-app purchases of virtual currency (Robux) and subscription benefits.",
      "stance": "risk",
      "quote": "Roblox may offer you access to additional benefits or other digital items provided by Roblox through paid subscriptions (“Roblox Subscription”)."
    },
    {
      "ref": "[D503]",
      "area": "money",
      "claim": "A parent reports that loot boxes are not mentioned, but virtual items are sold directly.",
      "stance": "neutral",
      "quote": "The Services may enable you to access certain Roblox-Owned Content for use with your avatar, such as clothing, accessories, or other digital items (collectively, “Roblox Marketplace Items” and together with the User Marketplace Items, the “Marketplace Items”)."
    },
    {
      "ref": "[D503]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data like email, phone number, and ID for account access and may share it with third parties.",
      "stance": "risk",
      "quote": "You may be asked to provide information like an email address, phone number, or a government-issued photo identification to access certain Content or features in Roblox Player."
    },
    {
      "ref": "[D503]",
      "area": "data",
      "claim": "A parent reports that users can request deletion of their data, but the policy does not guarantee full deletion.",
      "stance": "mitigation",
      "quote": "Deactivating or deleting your Account... terminates access to the Account, to your Content, to your Robux, and to any Content you have accessed or used on the Services, and we initiate the deletion of the data associated with the Account, subject to Roblox’s Privacy Policy and data retention policies."
    },
    {
      "ref": "[D503]",
      "area": "developer_record",
      "claim": "A parent reports no known fines or lawsuits against Roblox at this time.",
      "stance": "neutral",
      "quote": "Roblox Corporation (“we,” “us,” “our”) to allow users (“Users,” “your,” or “you”) to play, create, and connect."
    }
  ]
}
